import React from 'react';

import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { getRecipeByIdAsync } from '../@services/recipes.service';
import { IFullRecipe } from '../@types/recipes.types';
import RecipeEditBaseParams from '../components/RecipeEdit/RecipeEditBaseParams';
import RecipeEditStructure from '../components/RecipeEdit/RecipeEditStructure';

interface IRecipeEditPageProps {
  id_recipe: number;
}

const RecipeEditPage: React.FC<IRecipeEditPageProps> = ({ id_recipe }) => {
  const [err, setErr] = React.useState<Error>();
  const [isLoading, setIsLoading] = React.useState(true);
  const [recipeData, setRecipeData] = React.useState<IFullRecipe>();

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const rd = await getRecipeByIdAsync(id_recipe);
        setRecipeData(rd);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_recipe]);

  if (isLoading) return <PageLoader />;

  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!recipeData) return <PohAlert variant={AlertVariant.Danger}>Has no recipeData</PohAlert>;

  return (
    <Page title={`Редактирование рецепта ${recipeData.name}`}>
      <PohContainer>
        <PohBreadcrumbs
          data={[
            { href: '/recipes', text: 'Рецепты' },
            { href: `/recipes/${id_recipe}`, text: recipeData.name },
            { href: `/recipes/${id_recipe}/edit`, text: 'Редактирование', active: true },
          ]}
        />
        <PageHeader title={`Редактирование рецепта "${recipeData.name}"`}>&nbsp;</PageHeader>
        <PohRow>
          <PohCol sm={6}>
            <h3>Основные параметры</h3>
            <RecipeEditBaseParams id_recipe={id_recipe} recipeData={recipeData} />
          </PohCol>
          <PohCol sm={6}>
            <h3>Ингредиенты</h3>
            <RecipeEditStructure id_recipe={id_recipe} />
          </PohCol>
        </PohRow>
      </PohContainer>
    </Page>
  );
};

export default RecipeEditPage;
